// Process error information
const errorData = items[0].json;

return [{
  json: {
    error_analysis: {
      has_error: errorData.error,
      error_message: errorData.err_message,
      validation_status: errorData.validation_summary?.status,
      unmapped_fields: errorData.validation_summary?.unmapped_fields || [],
      warnings: errorData.validation_summary?.warnings || [],
      corrections: errorData.validation_summary?.corrections || [],
      processing_mode: errorData.metadata?.processing_mode,
      timestamp: new Date().toISOString()
    },
    recommendations: {
      data_quality_issues: [
        "Check for missing required fields",
        "Validate date formats (use YYYY-MM-DD)",
        "Ensure proper field naming conventions",
        "Remove special characters from names",
        "Provide valid phone number formats"
      ],
      next_steps: [
        "Clean source data",
        "Use Manual Override mode for complex mappings",
        "Enable detailed mapping for debugging",
        "Review field patterns in documentation"
      ]
    },
    retry_suggestions: {
      processing_mode: "manual",
      include_detailed_mapping: true,
      stop_on_error: false
    }
  }
}];

// Process successful transformation
const successData = items[0].json;

return [{
  json: {
    success_analysis: {
      resource_created: true,
      fhir_resource_type: successData.resource_type,
      resource_id: successData.fhir_resource?.id,
      validation_status: successData.validation_summary?.status,
      mapped_fields_count: successData.mapping_summary?.auto_detected || 0,
      total_input_fields: successData.mapping_summary?.total_input_fields || 0,
      mapping_success_rate: `${Math.round((successData.mapping_summary?.auto_detected / successData.mapping_summary?.total_input_fields) * 100)}%`,
      warnings: successData.validation_summary?.warnings || [],
      corrections: successData.validation_summary?.corrections || [],
      timestamp: new Date().toISOString()
    },
    quality_metrics: {
      auto_detection_confidence: successData.mapping_summary?.high_confidence || 0,
      needs_review_count: successData.mapping_summary?.needs_review || 0,
      transformation_quality: successData.validation_summary?.status === 'valid' ? 'High' : 
                             successData.validation_summary?.status === 'valid_with_warnings' ? 'Good' : 'Needs Improvement'
    },
    next_steps: [
      "Resource ready for FHIR server submission",
      "Review any warnings for data quality improvements",
      "Consider manual override for unmapped fields",
      "Validate against FHIR specification if needed"
    ]
  }
}];
